//! WASM guest-side `Context` implementation backed by the Component Model.
//!
//! Calls the `actr:workload/host` imports generated by [`super::generated`].
//! The 0.6.0 world uses real async Component Model imports. The generated host
//! calls are awaited directly, allowing the host's resident `run_concurrent`
//! region to suspend one invocation and interleave another on the same guest
//! instance.

use actr_protocol::{
    ActorResult, ActrError, ActrId, ActrType, ConnectionNotReadyInfo, PayloadType, RpcRequest,
};
use async_trait::async_trait;
use bytes::Bytes;
use futures_util::future::BoxFuture;
use prost::Message as ProstMessage;
use std::cell::RefCell;
use std::collections::HashMap;

use crate::{Context, Deliver, Dest, MediaSample, ReplyOutcome};

use super::context_helpers::{
    actr_id_from_wit, actr_id_to_wit, actr_type_from_wit, actr_type_to_wit, data_chunk_from_wit,
    data_chunk_to_wit, dest_to_wit, payload_type_to_wit,
};
use super::generated::actr::workload::host as wit_host;
use super::generated::actr::workload::types as wit_types;

/// Translate a WIT `actr-error` variant back into the framework's
/// [`ActrError`] — exact inverse of the host-side `actr_error_to_wit` in
/// `crates/actr-hyper/src/wasm/host.rs`.
pub(crate) fn wit_actr_error_to_proto(e: wit_types::ActrError) -> ActrError {
    match e {
        wit_types::ActrError::Unavailable(msg) => ActrError::Unavailable(msg),
        wit_types::ActrError::ConnectionNotReady(info) => {
            ActrError::ConnectionNotReady(wit_connection_not_ready_info_to_proto(info))
        }
        wit_types::ActrError::TimedOut => ActrError::TimedOut,
        wit_types::ActrError::NotFound(msg) => ActrError::NotFound(msg),
        wit_types::ActrError::PermissionDenied(msg) => ActrError::PermissionDenied(msg),
        wit_types::ActrError::InvalidArgument(msg) => ActrError::InvalidArgument(msg),
        wit_types::ActrError::UnknownRoute(msg) => ActrError::UnknownRoute(msg),
        wit_types::ActrError::DependencyNotFound(p) => ActrError::DependencyNotFound {
            service_name: p.service_name,
            message: p.message,
        },
        wit_types::ActrError::DecodeFailure(msg) => ActrError::DecodeFailure(msg),
        wit_types::ActrError::NotImplemented(msg) => ActrError::NotImplemented(msg),
        wit_types::ActrError::Internal(msg) => ActrError::Internal(msg),
        wit_types::ActrError::DeliveryUncertain(p) => ActrError::DeliveryUncertain {
            operation_id: p.operation_id,
            cause: p.cause,
        },
    }
}

/// Translate an [`ActrError`] into the WIT variant — used when the guest
/// runtime surfaces its own errors back through a fallible lifecycle hook.
pub(crate) fn proto_actr_error_to_wit(e: ActrError) -> wit_types::ActrError {
    match e {
        ActrError::Unavailable(msg) => wit_types::ActrError::Unavailable(msg),
        ActrError::ConnectionNotReady(info) => {
            wit_types::ActrError::ConnectionNotReady(proto_connection_not_ready_info_to_wit(info))
        }
        ActrError::TimedOut => wit_types::ActrError::TimedOut,
        ActrError::NotFound(msg) => wit_types::ActrError::NotFound(msg),
        ActrError::PermissionDenied(msg) => wit_types::ActrError::PermissionDenied(msg),
        ActrError::InvalidArgument(msg) => wit_types::ActrError::InvalidArgument(msg),
        ActrError::UnknownRoute(msg) => wit_types::ActrError::UnknownRoute(msg),
        ActrError::DependencyNotFound {
            service_name,
            message,
        } => wit_types::ActrError::DependencyNotFound(wit_types::DependencyNotFoundPayload {
            service_name,
            message,
        }),
        ActrError::DecodeFailure(msg) => wit_types::ActrError::DecodeFailure(msg),
        ActrError::NotImplemented(msg) => wit_types::ActrError::NotImplemented(msg),
        ActrError::Internal(msg) => wit_types::ActrError::Internal(msg),
        ActrError::DeliveryUncertain {
            operation_id,
            cause,
        } => wit_types::ActrError::DeliveryUncertain(wit_types::DeliveryUncertainPayload {
            operation_id,
            cause,
        }),
        // `ActrError` is `#[non_exhaustive]`: unmapped future variants map
        // to the generic Internal wire variant so they survive the WIT
        // boundary rather than being lost.
        other => wit_types::ActrError::Internal(format!("unmapped actr error: {other}")),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// ConnectionNotReadyInfo WIT ↔ protocol conversion helpers
// ─────────────────────────────────────────────────────────────────────────────

fn wit_connection_not_ready_info_to_proto(
    info: wit_types::ConnectionNotReadyInfo,
) -> ConnectionNotReadyInfo {
    ConnectionNotReadyInfo {
        retry_after_ms: info.retry_after_ms,
    }
}

fn proto_connection_not_ready_info_to_wit(
    info: ConnectionNotReadyInfo,
) -> wit_types::ConnectionNotReadyInfo {
    wit_types::ConnectionNotReadyInfo {
        retry_after_ms: info.retry_after_ms,
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// WasmContext
// ─────────────────────────────────────────────────────────────────────────────

/// WASM guest-side actor execution context, backed by the Component
/// Model host imports.
///
/// `WasmContext` is cheap to clone. Under the 0.6.0 async world the
/// identity triple (`self_id` / `caller_id` / `request_id`) is delivered
/// as an explicit `invocation-ctx` parameter rather than read back through
/// getter imports, and `ctx_token` keys this invocation in the host's
/// per-invocation table. Every outbound call (`call`, `tell`, `call-raw`,
/// `discover`, stream ops) threads `ctx_token` as the first argument of the
/// corresponding WIT import so the host recovers the right bridge even when
/// several invocations are in flight on one instance.
#[derive(Clone)]
pub(crate) struct WasmContext {
    pub(crate) ctx_token: u64,
    self_id: ActrId,
    caller_id: Option<ActrId>,
    request_id: String,
    expects_response: bool,
    reply_enabled: bool,
}

/// Synchronous host bridge used by the Rust framework's `Reply<T>` handle.
/// The WIT host function only enqueues the outcome; the host-side
/// `ReplyDeliver` performs the asynchronous transport work after returning.
struct WasmReplyDeliver {
    ctx_token: u64,
}

impl Deliver for WasmReplyDeliver {
    fn deliver(&self, outcome: ReplyOutcome) {
        let result = match outcome.result {
            Ok(payload) => {
                let payload = payload.to_vec();
                super::generated::actr::workload::host::reply_sync(self.ctx_token, &payload)
            }
            Err(error) => {
                let error = proto_actr_error_to_wit(error);
                super::generated::actr::workload::host::reply_error_sync(self.ctx_token, &error)
            }
        };
        if let Err(error) = result {
            panic!("Rust guest reply could not reach the host: {error:?}");
        }
    }
}

thread_local! {
    /// A Component Model guest runs cooperatively on one WASM thread. Keeping
    /// senders local lets ordinary generic handlers capture `C: Context`
    /// without manufacturing native-only `Send + Sync` bounds.
    ///
    /// One sender per active `data_chunks` subscription; the host runner
    /// queues DataChunk delivery behind the register import, so a stalled
    /// queue backpressures only this stream.
    static STREAM_SENDERS: RefCell<
        HashMap<String, futures_channel::mpsc::Sender<ActorResult<crate::DataChunkEvent>>>,
    > = RefCell::new(HashMap::new());
}

pub(crate) async fn dispatch_registered_stream(
    chunk: wit_types::DataChunk,
    sender: wit_types::ActrId,
    ctx_token: u64,
) -> ActorResult<()> {
    let chunk = data_chunk_from_wit(chunk);
    let sender = actr_id_from_wit(&sender);
    let tx = STREAM_SENDERS.with(|senders| senders.borrow().get(&chunk.stream_id).cloned());

    match tx {
        Some(mut tx) => {
            use futures_util::SinkExt;
            let stream_id = chunk.stream_id.clone();
            let event = crate::DataChunkEvent { chunk, sender };
            match tx.send(Ok(event)).await {
                Ok(()) => {
                    // Yield so consumer tasks spawned with `spawn_local` can
                    // start (and issue their host imports) before this export
                    // returns; the queue still preserves per-stream FIFO.
                    wit_bindgen::yield_async().await;
                    Ok(())
                }
                // The receiver was dropped without close() (best-effort Drop
                // path abandons the async host unregister). Remove the stale
                // entry and tear down the host registration with THIS live
                // invocation's token.
                Err(_) => {
                    STREAM_SENDERS.with(|senders| {
                        senders.borrow_mut().remove(&stream_id);
                    });
                    let _ = wit_host::unregister_stream(ctx_token, stream_id.clone()).await;
                    Err(ActrError::NotFound(format!(
                        "stream subscription for '{stream_id}' is gone"
                    )))
                }
            }
        }
        None => Err(ActrError::NotFound(format!(
            "no stream subscription for '{}'",
            chunk.stream_id
        ))),
    }
}

impl WasmContext {
    /// Build a context from the explicit `invocation-ctx` the host threads
    /// into every guest export.
    /// Carries the full identity triple plus the `ctx-token` used to route
    /// outbound host imports.
    pub(crate) fn from_invocation(inv: wit_types::InvocationCtx) -> Self {
        Self {
            ctx_token: inv.ctx_token,
            self_id: actr_id_from_wit(&inv.self_id),
            caller_id: inv.caller_id.as_ref().map(actr_id_from_wit),
            request_id: inv.request_id,
            expects_response: inv.expects_response,
            reply_enabled: inv.reply_enabled,
        }
    }

    pub(crate) fn reply_enabled(&self) -> bool {
        self.reply_enabled
    }

    /// Deliver a RETURN-mode response through the Component Model host
    /// boundary. Rust's framework dispatcher still returns the encoded bytes;
    /// the guest adapter converts that return into the same explicit host
    /// operation used by the foreign-language dispatchers.
    pub(crate) async fn reply_raw(&self, payload: Bytes) -> ActorResult<()> {
        wit_host::reply(self.ctx_token, payload.to_vec())
            .await
            .map_err(wit_actr_error_to_proto)
    }
}

#[async_trait(?Send)]
impl Context for WasmContext {
    fn self_id(&self) -> &ActrId {
        &self.self_id
    }

    fn caller_id(&self) -> Option<&ActrId> {
        self.caller_id.as_ref()
    }

    fn request_id(&self) -> &str {
        &self.request_id
    }

    fn expects_response(&self) -> bool {
        self.expects_response
    }

    fn reply_deliver(&self) -> Option<std::sync::Arc<dyn Deliver>> {
        self.reply_enabled.then(|| {
            std::sync::Arc::new(WasmReplyDeliver {
                ctx_token: self.ctx_token,
            }) as std::sync::Arc<dyn Deliver>
        })
    }

    fn claim_reply(&self) -> bool {
        self.reply_enabled
    }

    async fn call<R: RpcRequest>(
        &self,
        target: &Dest,
        request: R,
        timeout_ms: i64,
    ) -> ActorResult<R::Response> {
        let payload = request.encode_to_vec();
        // 0.6.0 async imports take OWNED params and a `ctx-token` first arg;
        // the call is `.await`ed (the host may suspend on real I/O).
        let result = wit_host::call(
            self.ctx_token,
            dest_to_wit(target),
            R::route_key().to_string(),
            payload,
            timeout_ms,
            payload_type_to_wit(R::payload_type()),
        )
        .await;
        match result {
            Ok(bytes) => R::Response::decode(bytes.as_slice())
                .map_err(|e| ActrError::DecodeFailure(format!("response decode failed: {e}"))),
            Err(e) => Err(wit_actr_error_to_proto(e)),
        }
    }

    async fn tell<R: RpcRequest>(&self, target: &Dest, message: R) -> ActorResult<()> {
        let payload = message.encode_to_vec();
        wit_host::tell(
            self.ctx_token,
            dest_to_wit(target),
            R::route_key().to_string(),
            payload,
            payload_type_to_wit(R::payload_type()),
        )
        .await
        .map_err(wit_actr_error_to_proto)
    }

    async fn data_chunks(
        &self,
        stream_id: String,
        options: crate::DataChunkStreamOptions,
    ) -> ActorResult<crate::DataChunkStream> {
        let capacity = crate::validate_stream_options(&options)?;
        let already_subscribed =
            STREAM_SENDERS.with(|senders| senders.borrow().contains_key(&stream_id));
        if already_subscribed {
            return Err(ActrError::InvalidArgument(format!(
                "stream '{stream_id}' already has an active subscription"
            )));
        }
        // Register host-side first. The runner queues DataChunk delivery behind
        // this invocation, so installing the guest queue immediately after
        // the awaited import cannot miss a delivery; this ordering also avoids
        // retaining a guest queue when host registration fails.
        wit_host::register_stream(self.ctx_token, stream_id.clone())
            .await
            .map_err(wit_actr_error_to_proto)?;
        let (tx, rx) = futures_channel::mpsc::channel(capacity);
        STREAM_SENDERS.with(|senders| {
            senders.borrow_mut().insert(stream_id.clone(), tx);
        });
        let cancel_stream_id = stream_id;
        // Cancel-only closer: the async host unregister import would need a
        // live invocation token, but close()/drop may run in an invocation
        // where the registering token is already retired. Host-side teardown
        // happens instead on the next on-data-chunk delivery, which calls the
        // unregister import with that invocation's live token (see
        // dispatch_registered_stream).
        let closer = crate::StreamCloser::new(Box::new(move || {
            STREAM_SENDERS.with(|senders| {
                senders.borrow_mut().remove(&cancel_stream_id);
            });
        }));
        Ok(crate::DataChunkStream::from_parts(rx, closer))
    }

    async fn data_chunk_sink(
        &self,
        target: &Dest,
        stream_id: String,
        payload_type: PayloadType,
    ) -> ActorResult<crate::DataChunkSink> {
        let ctx_token = self.ctx_token;
        let wit_dest = dest_to_wit(target);
        let wit_payload_type = payload_type_to_wit(payload_type);
        let send_fn: crate::SendDataChunkFn = Box::new(move |chunk| {
            let wit_dest = wit_dest.clone();
            Box::pin(async move {
                wit_host::send_data_chunk(
                    ctx_token,
                    wit_dest,
                    data_chunk_to_wit(chunk),
                    wit_payload_type,
                )
                .await
                .map_err(wit_actr_error_to_proto)
            })
        });
        crate::DataChunkSink::new(stream_id, payload_type, send_fn)
    }

    async fn discover_route_candidate(&self, target_type: &ActrType) -> ActorResult<ActrId> {
        wit_host::discover(self.ctx_token, actr_type_to_wit(target_type))
            .await
            .map(|id| actr_id_from_wit(&id))
            .map_err(wit_actr_error_to_proto)
    }

    async fn resolve_dependency(&self, alias: &str) -> ActorResult<ActrType> {
        wit_host::resolve_dependency(self.ctx_token, alias.to_string())
            .await
            .map(|actr_type| actr_type_from_wit(&actr_type))
            .map_err(wit_actr_error_to_proto)
    }

    async fn call_raw(
        &self,
        target: &ActrId,
        route_key: &str,
        payload: Bytes,
        timeout_ms: i64,
    ) -> ActorResult<Bytes> {
        self.call_raw_with_payload_type(
            target,
            route_key,
            PayloadType::RpcReliable,
            payload,
            timeout_ms,
        )
        .await
    }

    async fn call_raw_with_payload_type(
        &self,
        target: &ActrId,
        route_key: &str,
        payload_type: PayloadType,
        payload: Bytes,
        timeout_ms: i64,
    ) -> ActorResult<Bytes> {
        wit_host::call_raw(
            self.ctx_token,
            actr_id_to_wit(target),
            route_key.to_string(),
            payload.to_vec(),
            timeout_ms,
            payload_type_to_wit(payload_type),
        )
        .await
        .map(Bytes::from)
        .map_err(wit_actr_error_to_proto)
    }

    async fn register_media_track<F>(&self, _track_id: String, _callback: F) -> ActorResult<()>
    where
        F: Fn(MediaSample, ActrId) -> BoxFuture<'static, ActorResult<()>> + Send + Sync + 'static,
    {
        Err(ActrError::NotImplemented(
            "WebRTC media tracks are not supported in WASM environment".into(),
        ))
    }

    async fn unregister_media_track(&self, _track_id: &str) -> ActorResult<()> {
        Err(ActrError::NotImplemented(
            "WebRTC media tracks are not supported in WASM environment".into(),
        ))
    }

    async fn send_media_sample(
        &self,
        _target: &Dest,
        _track_id: &str,
        _sample: MediaSample,
    ) -> ActorResult<()> {
        Err(ActrError::NotImplemented(
            "WebRTC media tracks are not supported in WASM environment".into(),
        ))
    }

    async fn add_media_track(
        &self,
        _target: &Dest,
        _track_id: &str,
        _codec: &str,
        _media_type: &str,
    ) -> ActorResult<()> {
        Err(ActrError::NotImplemented(
            "WebRTC media tracks are not supported in WASM environment".into(),
        ))
    }

    async fn remove_media_track(&self, _target: &Dest, _track_id: &str) -> ActorResult<()> {
        Err(ActrError::NotImplemented(
            "WebRTC media tracks are not supported in WASM environment".into(),
        ))
    }
}
